      <button class="btn btn-primary" type="button" id="btnRestart">Пройти ещё раз</button>
    </div>
  </section>
</main>

<script>
(() => {
  "use strict";

  const testSection = document.getElementById("testSection");
  const resultSection = document.getElementById("resultSection");
  const tabs = Array.from(document.querySelectorAll("[data-step-btn]"));
  const panes = Array.from(document.querySelectorAll("[data-step-pane]"));
  const btnPrev = document.getElementById("btnPrev");
  const btnNext = document.getElementById("btnNext");
  const btnFinish = document.getElementById("btnFinish");
  const btnRestart = document.getElementById("btnRestart");
  const progress = document.getElementById("discProgress");
  const stepHint = document.getElementById("stepHint");
  const tabsScroller = document.querySelector(".tabs");

  const lists = Array.from(document.querySelectorAll(".disc-list"));
  const initialMarkup = new Map(lists.map((list) => [list, list.innerHTML]));

  const TYPE_NAMES = {
    d: "Доминирование",
    i: "Влияние",
    s: "Стабильность",
    c: "Соответствие"
  };

  let step = 0;

  /* ---------- шаги ---------- */
  const render = () => {
    tabs.forEach((tab) => {
      const active = Number(tab.dataset.stepBtn) === step;
      tab.classList.toggle("is-active", active);
      tab.setAttribute("aria-selected", active ? "true" : "false");
      tab.tabIndex = active ? 0 : -1;
    });

    panes.forEach((pane) => {
      pane.classList.toggle("is-active", Number(pane.dataset.stepPane) === step);
    });

    btnPrev.disabled = step === 0;
    btnNext.hidden = step === 7;
    btnFinish.hidden = step !== 7;
    progress.style.width = (((step + 1) / 8) * 100) + "%";
    stepHint.textContent = "Шаг " + (step + 1) + " из 8";

    const activeTab = tabs[step];
    if (activeTab && tabsScroller) {
      const left = activeTab.offsetLeft;
      const right = left + activeTab.offsetWidth;
      if (left < tabsScroller.scrollLeft || right > tabsScroller.scrollLeft + tabsScroller.clientWidth) {
        tabsScroller.scrollTo({
          left: Math.max(0, left - (tabsScroller.clientWidth - activeTab.offsetWidth) / 2),
          behavior: "smooth"
        });
      }
    }
  };

  const setStep = (next) => {
    step = Math.max(0, Math.min(7, next));
    render();
  };

  tabs.forEach((tab) => {
    tab.addEventListener("click", () => setStep(Number(tab.dataset.stepBtn)));
  });

  btnPrev.addEventListener("click", () => setStep(step - 1));
  btnNext.addEventListener("click", () => setStep(step + 1));

  /* ---------- перетаскивание (Pointer Events) ---------- */
  let drag = null;

  const finishDrag = (event) => {
    if (!drag) return;
    if (event && event.pointerId !== undefined && event.pointerId !== drag.pointerId) return;
    const item = drag.item;
    const list = drag.list;
    const moved = drag.moved;
    drag = null;
    item.classList.remove("is-dragging");
    list.classList.remove("is-reordering");
    if (moved) {
      item.classList.add("is-moved");
      window.setTimeout(() => item.classList.remove("is-moved"), 220);
    }
  };

  document.addEventListener("pointerdown", (event) => {
    if (resultSection.hidden === false) return;
    const item = event.target.closest(".disc-item");
    if (!item || !item.closest(".disc-list")) return;
    if (event.pointerType === "mouse" && event.button !== 0) return;
    if (event.pointerType !== "mouse" && !event.target.closest(".disc-handle")) return;

    event.preventDefault();
    item.focus({ preventScroll: true });
    drag = {
      item,
      list: item.parentNode,
      pointerId: event.pointerId,
      startY: event.clientY,
      moved: false
    };
    item.classList.add("is-dragging");
    drag.list.classList.add("is-reordering");
    try { item.setPointerCapture(event.pointerId); } catch (_) { /* ignore */ }
  }, { passive: false });

  document.addEventListener("pointermove", (event) => {
    if (!drag || event.pointerId !== drag.pointerId) return;
    if (Math.abs(event.clientY - drag.startY) > 2) drag.moved = true;
    event.preventDefault();

    const item = drag.item;
    const list = drag.list;
    const siblings = Array.from(list.children).filter((el) => el !== item);
    let placed = false;

    for (const sibling of siblings) {
      const rect = sibling.getBoundingClientRect();
      if (event.clientY < rect.top + rect.height / 2) {
        list.insertBefore(item, sibling);
        placed = true;
        break;
      }
    }
    if (!placed) list.appendChild(item);
  }, { passive: false });

  document.addEventListener("pointerup", finishDrag);
  document.addEventListener("pointercancel", finishDrag);
  document.addEventListener("lostpointercapture", finishDrag);

  document.addEventListener("dragstart", (event) => {
    if (event.target.closest(".disc-item")) event.preventDefault();
  });

  /* клавиатура: стрелки меняют порядок */
  document.addEventListener("keydown", (event) => {
    const item = event.target.closest(".disc-item");
    if (!item) return;
    if (event.key !== "ArrowUp" && event.key !== "ArrowDown") return;
    event.preventDefault();
    const sibling = event.key === "ArrowUp" ? item.previousElementSibling : item.nextElementSibling;
    if (!sibling) return;
    if (event.key === "ArrowUp") {
      item.parentNode.insertBefore(item, sibling);
    } else {
      item.parentNode.insertBefore(sibling, item);
    }
    item.focus({ preventScroll: true });
  });

  /* ---------- подсчёт ---------- */
  const collectScore = () => {
    const majors = [];
    const minors = [];

    document.querySelectorAll(".disc-list").forEach((list) => {
      const items = Array.from(list.children);
      if (items[0]) majors.push(items[0].dataset.type);
      if (items[3]) minors.push(items[3].dataset.type);
    });

    const count = (arr, type) => arr.reduce((sum, value) => sum + (value === type ? 1 : 0), 0);
    return {
      d: count(majors, "d") - count(minors, "d"),
      i: count(majors, "i") - count(minors, "i"),
      s: count(majors, "s") - count(minors, "s"),
      c: count(majors, "c") - count(minors, "c")
    };
  };

  const showResult = () => {
    const score = collectScore();
    const types = ["d", "i", "s", "c"];

    document.getElementById("scorePill").textContent =
      "D:" + score.d + ", I:" + score.i + ", S:" + score.s + ", C:" + score.c;

    types.forEach((type) => {
      const value = score[type];
      const valueEl = document.querySelector('[data-score="' + type + '"]');
      const fillEl = document.querySelector('[data-fill="' + type + '"]');
      if (valueEl) valueEl.textContent = value > 0 ? "+" + value : String(value);

      if (fillEl) {
        const width = Math.min(Math.abs(value) / 24, 1) * 50;
        fillEl.style.width = width + "%";
        fillEl.style.left = value >= 0 ? "50%" : (50 - width) + "%";
      }
    });

    const best = types.reduce((a, b) => (score[b] > score[a] ? b : a), types[0]);
    const note = document.getElementById("resultNote");
    note.innerHTML =
      "Наибольшее значение — <strong>" + best.toUpperCase() + " · " + TYPE_NAMES[best] + "</strong>. " +
      "Баллы считаются как в оригинале: выбранный как «наиболее» вариант добавляет +1, " +
      "выбранный как «наименее» — −1, затем баллы суммируются по каждому типу.";

    testSection.hidden = true;
    resultSection.hidden = false;
    window.scrollTo({ top: 0, behavior: "smooth" });
    const title = document.getElementById("resultTitle");
    if (title) title.focus({ preventScroll: true });
  };

  btnFinish.addEventListener("click", showResult);

  btnRestart.addEventListener("click", () => {
    lists.forEach((list) => {
      list.innerHTML = initialMarkup.get(list);
    });
    step = 0;
    resultSection.hidden = true;
    testSection.hidden = false;
    render();
    window.scrollTo({ top: 0, behavior: "smooth" });
  });

  render();
})();
</script>
</body>
